<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO Customer Action Center</title><style>:root{font-family:Inter,Arial,sans-serif;--navy:#06275c;--red:#e20b24;--bg:#f6f8fb;--line:#e1e6ee;--muted:#6d7b90;--green:#137346}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#071f4d}.wrap{max-width:1300px;margin:auto;padding:26px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.top h1{margin:0 0 5px;font-size:25px}.top p{margin:0;color:var(--muted);font-size:11px}.badge{padding:7px 10px;border-radius:999px;background:#e9eff8;font-size:9px;font-weight:800}.notice{padding:11px 13px;background:#e9f7ef;color:#176940;border-radius:9px;margin-bottom:12px;font-size:10px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px}.metric,.panel{background:#fff;border:1px solid var(--line);border-radius:12px}.metric{padding:14px}.metric span{font-size:9px;color:var(--muted)}.metric b{display:block;font-size:24px;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{padding:16px}.panel h2{font-size:14px;margin:0 0 12px}.item{padding:10px 0;border-bottom:1px solid #edf1f5;display:flex;justify-content:space-between;gap:10px}.item:last-child{border-bottom:0}.item b{font-size:10px}.item small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.action{font-size:9px;font-weight:800;color:#225d9c;text-decoration:none}.empty{padding:20px;text-align:center;color:var(--muted);font-size:10px}.back,.submit,.accept,.revisit{display:inline-flex;color:#fff;padding:8px 11px;border-radius:7px;text-decoration:none;font-size:9px;font-weight:800;border:0;cursor:pointer}.back,.submit{background:var(--navy)}.accept{background:var(--green)}.revisit{background:var(--red)}.back{margin-top:16px}.mini-form{display:grid;gap:5px;min-width:210px}.mini-form textarea,.mini-form input[type=file]{width:100%;border:1px solid #d8e0ea;border-radius:6px;padding:7px;font-size:9px;background:#fff}.mini-form textarea{min-height:46px}.inline-actions{display:grid;gap:6px;min-width:220px}.history{margin-top:12px}.state-open{color:#986000}.state-resolved{color:var(--green)}@media(max-width:900px){.summary{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.item{flex-direction:column}.mini-form,.inline-actions{min-width:0}}@media(max-width:520px){.summary{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><main class="wrap">@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif<div class="top"><div><h1>Action Required From You</h1><p>Phase 2 customer workflow center · {{ str_replace('_',' ',$role) }}</p></div><span class="badge">{{ $total }} open actions</span></div><section class="summary"><div class="metric"><span>Quotations</span><b>{{ $quotations->count() }}</b></div><div class="metric"><span>Work Acceptance</span><b>{{ $workOrders->count() }}</b></div><div class="metric"><span>Invoices Due</span><b>{{ $invoices->count() }}</b></div><div class="metric"><span>Contract Renewals</span><b>{{ $contracts->count() }}</b></div><div class="metric"><span>Unread Messages</span><b>{{ $unread }}</b></div></section><div class="grid"><section class="panel"><h2>Quotations Awaiting Your Decision</h2>@forelse($quotations as $q)<div class="item"><div><b>{{ $q->quotation_no }} · {{ number_format((float)$q->amount,2) }} {{ $q->currency }}</b><small>{{ $q->status }}</small></div><a class="action" href="{{ route('customer.section','quotations') }}">Review quotation →</a></div>@empty<div class="empty">No quotation decisions required.</div>@endforelse</section><section class="panel"><h2>Completed Work Awaiting Acceptance</h2>@forelse($workOrders as $wo)<div class="item"><div><b>{{ $wo->work_order_no }} · {{ $wo->asset?->name }}</b><small>Completed {{ $wo->completed_at?->diffForHumans() }}</small></div><div class="inline-actions"><form method="POST" action="{{ route('customer.work-acceptance.decide',$wo) }}">@csrf<input type="hidden" name="decision" value="ACCEPT"><button class="accept">Accept Work</button></form><form class="mini-form" method="POST" action="{{ route('customer.work-orders.revisit',$wo) }}">@csrf<textarea name="notes" required placeholder="What needs to be revisited?"></textarea><button class="revisit">Request Revisit</button></form></div></div>@empty<div class="empty">No work orders awaiting acceptance.</div>@endforelse</section><section class="panel"><h2>Invoices Requiring Attention</h2>@forelse($invoices as $invoice)<div class="item"><div><b>{{ $invoice->document_no }} · {{ number_format((float)$invoice->open_amount,2) }} {{ $invoice->currency }}</b><small>Due {{ $invoice->due_date?->format('Y-m-d') }}</small></div><div class="inline-actions"><form class="mini-form" method="POST" action="{{ route('customer.invoices.query',$invoice) }}">@csrf<textarea name="notes" required placeholder="Question or payment clarification"></textarea><button class="submit">Send Query to Finance</button></form><form class="mini-form" method="POST" enctype="multipart/form-data" action="{{ route('customer.invoices.payment-proof',$invoice) }}">@csrf<input type="file" name="proof" accept=".pdf,.jpg,.jpeg,.png" required><textarea name="notes" placeholder="Payment reference or notes"></textarea><button class="accept">Upload Payment Proof</button></form></div></div>@empty<div class="empty">No invoices require attention.</div>@endforelse</section><section class="panel"><h2>Contracts Approaching Renewal</h2>@forelse($contracts as $contract)<div class="item"><div><b>{{ $contract->contract_no }} · {{ $contract->title }}</b><small>Ends {{ $contract->ends_on?->format('Y-m-d') }}</small></div><form class="mini-form" method="POST" action="{{ route('customer.contracts.renewal-request',$contract) }}">@csrf<textarea name="notes" placeholder="Renewal requirements or changes"></textarea><button class="submit">Request Renewal</button></form></div>@empty<div class="empty">No contract renewals due soon.</div>@endforelse</section></div><section class="panel history"><h2>My Submitted Actions</h2>@forelse($submittedActions as $a)<div class="item"><div><b>{{ str_replace('_',' ',$a->action_type) }}</b><small>{{ $a->submitted_at?->format('Y-m-d H:i') }} · {{ $a->notes ?: 'No note' }}</small>@if($a->resolution_notes)<small><strong>UNIFCO:</strong> {{ $a->resolution_notes }}</small>@endif</div><span class="badge {{ $a->status==='OPEN'?'state-open':'state-resolved' }}">{{ $a->status }}</span></div>@empty<div class="empty">No submitted actions yet.</div>@endforelse</section><a class="back" href="{{ route('customer.portal') }}">← Back to Customer 360</a></main></body></html>